import { useEffect, useState } from "react";

/** 状態の問い合わせ先 (同一オリジンのみ。外部への送信は行わない) */
const STATUS_ENDPOINT = "/api/soloptilink-status";

/** ポーリング周期 15 秒 (ConnectionGuard と同周期) */
const POLL_INTERVAL_MS = 15000;

/** 表示する状態。hidden = 何も描画しない (complete・取得失敗・状態ファイル欠落) */
type BeaconState = "generating" | "verifying" | "hidden";

type BannerStyle = {
  title: string;
  note: string;
  background: string;
  color: string;
  accent: string;
};

const BANNERS: Record<"generating" | "verifying", BannerStyle> = {
  // 生成中: 青
  generating: {
    title: "ただいまシステムを構築中です",
    note: "この間に表示されるエラーは不具合ではありません。完成のお知らせが出るまでお待ちください。",
    background: "#1d4ed8",
    color: "#ffffff",
    accent: "#bfdbfe",
  },
  // 検証中: 黄
  verifying: {
    title: "動作検証を実行しています",
    note: "全画面・ボタンの自動確認中です。この間に操作すると検証をやり直します。",
    background: "#fde047",
    color: "#422006",
    accent: "#a16207",
  },
};

/**
 * 生成物の状態表示バナー。
 * 状態は API 経由でのみ取得し、取得できない場合は【必ず非表示】に倒す
 * (状態表示の故障が新たな顧客可視エラーになってはならない)。
 */
export default function StatusBeacon() {
  const [state, setState] = useState<BeaconState>("hidden");

  useEffect(() => {
    let alive = true;
    let timer: number | null = null;

    const poll = async () => {
      try {
        const res = await fetch(STATUS_ENDPOINT, { cache: "no-store" });
        if (!alive) return;
        if (!res.ok) {
          // API 失敗 (404 / 500 等) は非表示へ倒す
          setState("hidden");
          return;
        }
        const data: unknown = await res.json();
        if (!alive) return;
        const raw = (data as { state?: unknown } | null)?.state;
        if (raw === "generating" || raw === "verifying") {
          setState(raw);
        } else {
          // complete / 不明値 / 状態ファイル欠落 → 非表示
          setState("hidden");
        }
      } catch (e) {
        // 通信断・JSON 破損なども握り潰して非表示 (画面にエラーを出さない)
        if (alive) setState("hidden");
      }
    };

    void poll();
    timer = window.setInterval(() => {
      void poll();
    }, POLL_INTERVAL_MS);

    return () => {
      alive = false;
      if (timer !== null) window.clearInterval(timer);
    };
  }, []);

  // 完成 (complete) と取得失敗は何も描画しない = 完成状態で顧客可視ノイズを出さない
  if (state !== "generating" && state !== "verifying") return null;

  const banner = BANNERS[state];

  return (
    <div
      data-soloptilink-status-beacon={state}
      role="status"
      aria-live="polite"
      style={{
        position: "fixed",
        left: 0,
        right: 0,
        bottom: 0,
        zIndex: 2147483644,
        // 画面の最下部に固定で敷くため、この帯の下にあるボタンを覆ってしまう。
        // クリックを素通りさせて「押しても反応しないボタン」を作らない
        // (2026-08-28 実測: 登録画面の「登録する」がこの帯に覆われて押せなかった)
        pointerEvents: "none",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: 10,
        padding: "10px 16px",
        background: banner.background,
        color: banner.color,
        fontSize: 13,
        fontWeight: 600,
        lineHeight: 1.5,
        textAlign: "center",
        fontFamily:
          "-apple-system,BlinkMacSystemFont,'Hiragino Sans','Noto Sans JP',sans-serif",
      }}
    >
      <span
        aria-hidden="true"
        style={{
          width: 8,
          height: 8,
          borderRadius: 9999,
          background: banner.accent,
          display: "inline-block",
          flex: "0 0 auto",
          animation: "solopti-sb-blink 1.2s ease-in-out infinite",
        }}
      />
      <span>
        {banner.title}
        <span style={{ fontWeight: 400, marginLeft: 8 }}>{banner.note}</span>
      </span>
      <style>
        {"@keyframes solopti-sb-blink{0%,100%{opacity:1}50%{opacity:0.25}}"}
      </style>
    </div>
  );
}

export { StatusBeacon };
